// fix7: governess-beat histories written by the pre-fix7 live journal, as an
// upgraded host inherits them. The fixtures (tests/fixtures/temporal-replay/
// governess-journal, regenerated by scripts/record-governess-journal-
// histories.ts) were written by the journal writer, journal client and
// committed workflow bundle of 4439b2e7 (owner memo `loopRepoId`) and
// ec185ba1 (no memo), under `governess-beat:<runId>`, each left RUNNING:
// once with no worker on the queue, as production runs, once with a worker,
// so the history holds completed workflow tasks to replay. This closes the
// runbook's open item "governess beat histories written by the live journal
// itself". Each named check fails if the thing it names is absent:
//
//   recorded   — the four histories are what their manifest says: legacy
//                ids, the recorded memo, one signal per journal record, the
//                gov-6 golden journal.
//   fold       — this checkout's history reader folds each recorded history
//                into exactly the journal its writer held.
//   replay     — each history with completed tasks replays on this
//                checkout's shipped bundle and on a build of its source; a
//                control bundle that refuses `append_record` fails them.
//   answers    — each recorded start and signal, sent again to a worker on
//                this checkout's bundle, answers the `journal` query with the
//                recorded journal (and as the recording worker answered).
//   transition — on a production-shaped (no worker) recorded execution, this
//                checkout's journal for the same run never reads or signals
//                it; the owner's close terminates it; another repo with the
//                same run id never signals, reads or closes it; an execution
//                with no memo is closed by nobody.

import {
  afterAll,
  beforeAll,
  describe,
  expect,
  setDefaultTimeout,
  test,
} from "bun:test";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Client, defaultPayloadConverter } from "@temporalio/client";
import { historyFromJSON } from "@temporalio/common/lib/proto-utils";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { bundleWorkflowCode, Worker } from "@temporalio/worker";
import {
  closeGovernessBeatWorkflow,
  createGovernessBeatWorkflowControl,
} from "../../src/loop/governess-beat-close";
import {
  governessBeatLegacyWorkflowId,
  governessBeatOwnedWorkflowId,
  governessBeatOwner,
} from "../../src/loop/governess-beat-identity";
import {
  readGovernessJournal,
  replaceGovernessJournal,
} from "../../src/loop/governess-journal";
import type { GovernessControlRecord } from "../../src/loop/governess-journal-core";
import {
  attachGovernessJournalBackend,
  createGovernessTemporalJournalClient,
  type GovernessHistoryEvent,
  governessJournalFromHistoryEvents,
} from "../../src/loop/governess-temporal-journal";
import { createRunManifest } from "../../src/loop/run-state";
import { TemporalWorkflowPort } from "../../src/loop/temporal-workflow-port";
import {
  currentBundleCode,
  LOOP_FORK_ROOT,
} from "../support/temporal-replay-builds";

setDefaultTimeout(120_000);

const DIR = join(
  LOOP_FORK_ROOT,
  "tests/fixtures/temporal-replay/governess-journal"
);
const GOLDEN = join(
  LOOP_FORK_ROOT,
  "tests/fixtures/governess/beat-journal.golden.jsonl"
);
const OTHER_REPO = "other-repo-0000000000b2";
const PRODUCTION_QUEUE = "loop-governess";

interface Entry {
  file: string;
  journalQuery?: { value: unknown };
  label: string;
  memo: Record<string, unknown>;
  records: GovernessControlRecord[];
  ref: string;
  runId: string;
  status: string;
  taskQueue: string;
  variant: "noWorker" | "worker";
  workflowId: string;
}

const manifest = JSON.parse(
  readFileSync(join(DIR, "manifest.json"), "utf8")
) as {
  histories: Entry[];
  ownerRepo: string;
  schema: string;
};
const OWNER_REPO = manifest.ownerRepo;

interface RawEvent {
  eventType: string;
}

const rawHistoryOf = (entry: Entry): { events: RawEvent[] } =>
  JSON.parse(readFileSync(join(DIR, entry.file), "utf8"));

const historyOf = (entry: Entry) => historyFromJSON(rawHistoryOf(entry));

const decode = (payload: unknown): unknown =>
  defaultPayloadConverter.fromPayload(
    payload as Parameters<typeof defaultPayloadConverter.fromPayload>[0]
  );

const entryOf = (label: string, variant: Entry["variant"]): Entry => {
  const found = manifest.histories.find(
    (entry) => entry.label === label && entry.variant === variant
  );
  if (!found) {
    throw new Error(`no fixture ${label} ${variant}`);
  }
  return found;
};

// Control ids are random in the file writer: alias them by first appearance.
const normalize = (records: readonly GovernessControlRecord[]): string => {
  const ids = new Map<string, string>();
  return records
    .map((record) => {
      if (!ids.has(record.controlId)) {
        ids.set(record.controlId, `control-${ids.size + 1}`);
      }
      return JSON.stringify({
        ...record,
        controlId: ids.get(record.controlId),
      });
    })
    .join("\n");
};

const silentLogger = {
  debug: () => undefined,
  error: () => undefined,
  info: () => undefined,
  log: () => undefined,
  trace: () => undefined,
  warn: () => undefined,
};

const bundleOf = async (workflowsPath: string): Promise<string> =>
  (await bundleWorkflowCode({ logger: silentLogger as never, workflowsPath }))
    .code;

interface RecordedRun {
  signals: { arg: unknown; name: string }[];
  start: unknown;
}

const recordedRunOf = (entry: Entry): RecordedRun => {
  const history = historyOf(entry);
  const first = (payloads: unknown): unknown => {
    const [payload] = (payloads ?? []) as unknown[];
    if (!payload) {
      throw new Error(`${entry.file}: an event without its payload`);
    }
    return decode(payload);
  };
  let start: unknown;
  const signals: RecordedRun["signals"] = [];
  for (const event of history.events ?? []) {
    const started = event.workflowExecutionStartedEventAttributes;
    if (started) {
      start = first(started.input?.payloads);
    }
    const signaled = event.workflowExecutionSignaledEventAttributes;
    if (signaled) {
      signals.push({
        arg: first(signaled.input?.payloads),
        name: signaled.signalName ?? "",
      });
    }
  }
  if (start === undefined) {
    throw new Error(`${entry.file}: no start event`);
  }
  return { signals, start };
};

const goldenRecords = (): GovernessControlRecord[] =>
  readFileSync(GOLDEN, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line) as GovernessControlRecord);

describe("recorded legacy journal histories", () => {
  test("recorded: four histories, legacy ids, the recorded memo, one signal per record, the golden journal", () => {
    expect(manifest.schema).toBe("governess-journal-fixtures.v1");
    expect(
      manifest.histories.map((entry) => `${entry.label} ${entry.variant}`)
    ).toEqual([
      "installed-4439b2e7 noWorker",
      "installed-4439b2e7 worker",
      "first-journal-ec185ba1 noWorker",
      "first-journal-ec185ba1 worker",
    ]);
    for (const entry of manifest.histories) {
      const name = `${entry.label} ${entry.variant}`;
      expect(entry.workflowId, name).toBe(
        governessBeatLegacyWorkflowId(entry.runId)
      );
      expect(entry.status, name).toBe("RUNNING");
      expect(entry.memo, name).toEqual(
        entry.label.startsWith("installed-") ? { loopRepoId: OWNER_REPO } : {}
      );
      const types = rawHistoryOf(entry).events.map((event) => event.eventType);
      expect(
        types.filter(
          (type) => type === "EVENT_TYPE_WORKFLOW_EXECUTION_SIGNALED"
        ).length,
        name
      ).toBe(entry.records.length);
      expect(types.includes("EVENT_TYPE_WORKFLOW_TASK_COMPLETED"), name).toBe(
        entry.variant === "worker"
      );
      expect(entry.taskQueue, name).toBe(
        entry.variant === "worker"
          ? "loop-governess-replay-worker"
          : PRODUCTION_QUEUE
      );
      expect(normalize(entry.records), name).toBe(normalize(goldenRecords()));
    }
  });

  test("fold: this checkout's reader folds each recorded history into exactly its writer's journal", () => {
    for (const entry of manifest.histories) {
      const folded = governessJournalFromHistoryEvents(
        (historyOf(entry).events ?? []) as GovernessHistoryEvent[],
        decode as (payload: unknown) => unknown
      );
      expect(folded, `${entry.label} ${entry.variant}`).toEqual(entry.records);
    }
  });
});

describe("Temporal replay of the recorded journal histories on this checkout's bundle", () => {
  const replayed = new Map<string, Map<string, string>>();
  const withTasks = manifest.histories.filter(
    (entry) => entry.variant === "worker"
  );

  const replay = async (
    code: string,
    entries: readonly Entry[]
  ): Promise<Map<string, string>> => {
    const results = new Map<string, string>();
    for await (const result of Worker.runReplayHistories(
      { replayName: "governess-legacy-replay", workflowBundle: { code } },
      entries.map((entry) => ({
        history: rawHistoryOf(entry),
        workflowId: entry.workflowId,
      }))
    )) {
      results.set(
        result.workflowId,
        result.error ? `${result.error.name}: ${result.error.message}` : "ok"
      );
    }
    return results;
  };

  beforeAll(async () => {
    replayed.set("shipped", await replay(currentBundleCode(), withTasks));
    replayed.set(
      "source",
      await replay(
        await bundleOf(join(LOOP_FORK_ROOT, "src/loop/temporal-workflow.ts")),
        withTasks
      )
    );
    replayed.set(
      "control",
      await replay(
        await bundleOf(join(DIR, "refuse-append-workflow.ts")),
        withTasks
      )
    );
  }, 180_000);

  for (const entry of manifest.histories.filter(
    (candidate) => candidate.variant === "worker"
  )) {
    test(`replay: ${entry.label} replays on the shipped bundle and on a build of the current source`, () => {
      expect(replayed.get("shipped")?.get(entry.workflowId)).toBe("ok");
      expect(replayed.get("source")?.get(entry.workflowId)).toBe("ok");
    });
  }

  test("replay control: a bundle that refuses append_record fails every recorded history", () => {
    const control = replayed.get("control");
    expect(control?.size).toBe(withTasks.length);
    for (const entry of withTasks) {
      expect(control?.get(entry.workflowId), entry.label).toStartWith(
        "ReplayError: Replay failed due workflow task failure"
      );
    }
  });
});

describe("recorded legacy executions on a local Temporal server", () => {
  let environment: TestWorkflowEnvironment;
  let client: Client;

  beforeAll(async () => {
    environment = await TestWorkflowEnvironment.createLocal();
    client = new Client({
      connection: environment.connection,
      identity: "governess-legacy-replay-client",
      namespace: environment.namespace,
    });
  }, 180_000);

  afterAll(async () => {
    await environment?.teardown();
  });

  // The recorded execution again: its start, memo and every signal, on `queue`.
  const recreate = async (entry: Entry, queue: string): Promise<void> => {
    const run = recordedRunOf(entry);
    const handle = await client.workflow.start("temporalWorkflow", {
      args: [run.start],
      ...(Object.keys(entry.memo).length > 0 ? { memo: entry.memo } : {}),
      taskQueue: queue,
      workflowId: entry.workflowId,
    });
    for (const signal of run.signals) {
      await handle.signal(signal.name, signal.arg);
    }
  };

  const signalCount = async (workflowId: string): Promise<number> =>
    (
      (await client.workflow.getHandle(workflowId).fetchHistory()).events ?? []
    ).filter((event) => event.workflowExecutionSignaledEventAttributes).length;

  const statusOf = async (workflowId: string): Promise<string> =>
    (await client.workflow.getHandle(workflowId).describe()).status.name;

  const journalClient = (ownerRepoId: string) =>
    createGovernessTemporalJournalClient({
      client: client.workflow,
      decode,
      ownerRepoId,
      settleTimeoutMs: 10_000,
      taskQueue: PRODUCTION_QUEUE,
    });

  const closeAs = (repoId: string, runId: string) =>
    closeGovernessBeatWorkflow({
      control: createGovernessBeatWorkflowControl({ client: client.workflow }),
      manifest: createRunManifest({
        cwd: "/repo",
        mode: "paired",
        pid: 1,
        repoId,
        runId,
        state: "stopped",
      }),
      reason: "test",
      repoId,
      runId,
      taskQueue: PRODUCTION_QUEUE,
    });

  // A governess start of `repoId`'s run whose file journal holds `records`.
  const startJournal = async (
    repoId: string,
    runId: string,
    records: readonly GovernessControlRecord[]
  ) => {
    const journalFile = join(
      mkdtempSync(join(tmpdir(), "gov7-legacy-")),
      "governess-control.jsonl"
    );
    replaceGovernessJournal(journalFile, [...records]);
    const backend = await attachGovernessJournalBackend({
      connect: async () => journalClient(repoId),
      journalFile,
      ownerRepoId: repoId,
      runId,
      temporal: {
        address: "injected",
        namespace: "injected",
        taskQueue: PRODUCTION_QUEUE,
      },
    });
    if (backend.kind !== "temporal") {
      throw new Error("expected the Temporal backend");
    }
    await backend.close();
    return { backend, journalFile };
  };

  test("answers: every recorded execution, sent again to this checkout's bundle, answers journal as recorded", async () => {
    const queue = `gov7-legacy-answers-${process.pid}`;
    const worker = await Worker.create({
      connection: environment.nativeConnection,
      identity: "gov7-legacy-answers",
      maxCachedWorkflows: 0,
      namespace: environment.namespace,
      taskQueue: queue,
      workflowBundle: { code: currentBundleCode() },
    });
    const running = worker.run();
    const port = new TemporalWorkflowPort(client.workflow, {
      taskQueue: queue,
    });
    try {
      for (const entry of manifest.histories) {
        await recreate(entry, queue);
        let answered: unknown;
        for (let attempt = 0; attempt < 500; attempt += 1) {
          answered = (
            await port.query({ name: "journal", workflowId: entry.workflowId })
          ).value;
          if (
            Array.isArray(answered) &&
            answered.length === entry.records.length
          ) {
            break;
          }
          await new Promise((resolve) => setTimeout(resolve, 10));
        }
        const name = `${entry.label} ${entry.variant}`;
        expect(answered, name).toEqual(entry.records);
        if (entry.journalQuery) {
          expect(answered, name).toEqual(entry.journalQuery.value);
        }
        await client.workflow
          .getHandle(entry.workflowId)
          .terminate("recorded answers compared");
      }
    } finally {
      worker.shutdown();
      await running;
    }
  });

  test("transition: another repo with the same run id never signals, reads or closes the owner's legacy execution", async () => {
    const entry = entryOf("installed-4439b2e7", "noWorker");
    await recreate(entry, PRODUCTION_QUEUE);
    const before = await signalCount(entry.workflowId);
    expect(before).toBe(entry.records.length);

    // The other repo's own run with the colliding id journals and stops.
    const [first] = goldenRecords();
    const { backend } = await startJournal(
      OTHER_REPO,
      entry.runId,
      first ? [first] : []
    );
    // Recovery found its own history empty (the whole file was backfilled)
    // and rewrote nothing from the owner's 11-record legacy journal.
    expect(backend.recovery).toMatchObject({
      backfilled: 1,
      rewroteFile: false,
      temporalRecords: 1,
    });
    expect(
      await journalClient(OTHER_REPO).readRecords(entry.runId)
    ).toHaveLength(1);
    const closed = await closeAs(OTHER_REPO, entry.runId);
    expect(closed).toEqual({
      legacy: {
        detail: `owned by ${OWNER_REPO}`,
        outcome: "refused-foreign",
        workflowId: entry.workflowId,
      },
      outcome: "terminated",
      workflowId: governessBeatOwnedWorkflowId(
        governessBeatOwner({
          repoId: OTHER_REPO,
          runId: entry.runId,
          taskQueue: PRODUCTION_QUEUE,
        })
      ),
    });
    expect(await statusOf(entry.workflowId)).toBe("RUNNING");
    expect(await signalCount(entry.workflowId)).toBe(before);
    await client.workflow.getHandle(entry.workflowId).terminate("test done");
  });

  test("transition: the owner's next governess backfills its file into the new id, never touches the legacy execution, and its close terminates both", async () => {
    const entry = entryOf("installed-4439b2e7", "noWorker");
    await recreate(entry, PRODUCTION_QUEUE);
    const { backend, journalFile } = await startJournal(
      OWNER_REPO,
      entry.runId,
      entry.records
    );
    expect(backend.recovery).toMatchObject({
      backfilled: entry.records.length,
      historyComplete: true,
      temporalRecords: entry.records.length,
    });
    expect(readGovernessJournal(journalFile)).toEqual(entry.records);
    expect(await journalClient(OWNER_REPO).readRecords(entry.runId)).toEqual(
      entry.records
    );
    expect(await signalCount(entry.workflowId)).toBe(entry.records.length);

    const closed = await closeAs(OWNER_REPO, entry.runId);
    expect(closed).toMatchObject({
      legacy: { outcome: "terminated", workflowId: entry.workflowId },
      outcome: "terminated",
    });
    expect(await statusOf(entry.workflowId)).toBe("TERMINATED");
    // Terminated, not deleted: the legacy journal stays readable.
    const events = (
      await client.workflow.getHandle(entry.workflowId).fetchHistory()
    ).events as GovernessHistoryEvent[];
    expect(governessJournalFromHistoryEvents(events, decode as never)).toEqual(
      entry.records
    );
  });

  test("transition: a legacy execution with no owner memo is closed by nobody", async () => {
    const entry = entryOf("first-journal-ec185ba1", "noWorker");
    await recreate(entry, PRODUCTION_QUEUE);
    for (const repoId of [OWNER_REPO, OTHER_REPO]) {
      const closed = await closeAs(repoId, entry.runId);
      expect(closed.legacy, repoId).toEqual({
        detail: "carries no owner memo",
        outcome: "refused-unowned",
        workflowId: entry.workflowId,
      });
    }
    expect(await statusOf(entry.workflowId)).toBe("RUNNING");
    expect(await signalCount(entry.workflowId)).toBe(entry.records.length);
    await client.workflow.getHandle(entry.workflowId).terminate("test done");
  });
});
